import{_ as o,o as a,c as t,a0 as l}from"./chunks/framework.jwovEGr5.js";const b=JSON.parse('{"title":"图片转PDF","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"电脑知识/图片转PDF.md","filePath":"电脑知识/图片转PDF.md"}'),i={name:"电脑知识/图片转PDF.md"};function c(d,e,p,r,s,n){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="图片转pdf" tabindex="-1">图片转PDF <a class="header-anchor" href="#图片转pdf" aria-label="Permalink to &quot;图片转PDF&quot;">​</a></h1><h2 id="打印pdf" tabindex="-1">打印PDF <a class="header-anchor" href="#打印pdf" aria-label="Permalink to &quot;打印PDF&quot;">​</a></h2><p>图片所需格式：<code>.png``.jpg</code></p><p><strong>步骤</strong></p><ol><li>选中需要打印的图片（按住shift可以快速选中）</li></ol><blockquote><p>注意图片顺序需要正序排列（即从上到下，从左到右）</p></blockquote><ol start="2"><li>右键第一张图片（最上最左），选择打印</li><li>打印机选择<code>Microsoft Print to PDF</code>，右侧选择需要的格式，进行打印</li></ol><blockquote><p>预览图即为打印出的PDF样式，不存在二次旋转</p></blockquote><ol start="4"><li>选择PDF的保存地址，点击确定，等待打印完成</li></ol><h2 id="其他格式的图片" tabindex="-1">其他格式的图片 <a class="header-anchor" href="#其他格式的图片" aria-label="Permalink to &quot;其他格式的图片&quot;">​</a></h2><p>例如<code>.webp</code>等格式图片无法右键打印，需要全部转格式后再进行操作</p><h3 id="bat命令" tabindex="-1">bat命令 <a class="header-anchor" href="#bat命令" aria-label="Permalink to &quot;bat命令&quot;">​</a></h3><p>此方法需要将待处理图片放入一个独立文件夹（防止操作影响其它图片）</p><ol><li>新建文件夹，放入待处理图片</li><li>在该文件夹内部新建文本文档，文本输入<code>ren *待转化格式 *转化后格式</code></li></ol><blockquote><p><code>.</code>和空格都不能省略</p></blockquote><p>示例：<code>.webp</code>转<code>.png</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ren *.webp *.png</span></span></code></pre></div><ol start="3"><li>保存后叉掉文本文档，将文件扩展名改为<code>.bat</code></li></ol><blockquote><p>没有扩展名：点击上方栏的<code>查看</code>，勾选<code>文件扩展名</code></p></blockquote><ol start="4"><li>双击运行<code>.bat</code>文件，满足命令条件的文件便会被更改</li><li>之后，便可以按照<a href="#打印pdf">打印PDF</a>的步骤进行操作</li></ol>',20)])])}const u=o(i,[["render",c]]);export{b as __pageData,u as default};
